CREATE SEQUENCE public.command_report_seq;
CREATE TABLE public.reporting_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('Department Head','Deputy Commandant','Deputy Commandant Administration','Commandant','Chief Procurement Officer')),office_id uuid REFERENCES public.offices(id),officer_id uuid NOT NULL REFERENCES public.officers(id),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE NULLS NOT DISTINCT(kind,office_id));
GRANT SELECT ON public.reporting_lines TO authenticated; GRANT ALL ON public.reporting_lines TO service_role;
ALTER TABLE public.reporting_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointment_read ON public.reporting_lines FOR SELECT TO authenticated USING(true);
CREATE TRIGGER audit_reporting_lines AFTER INSERT OR UPDATE OR DELETE ON public.reporting_lines FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.daily_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_number text NOT NULL UNIQUE DEFAULT ('LNPATS/DAR/'||to_char(now(),'YYYY')||'/'||lpad(nextval('public.command_report_seq')::text,6,'0')),officer_id uuid NOT NULL REFERENCES public.officers(id),created_by uuid NOT NULL,report_date date NOT NULL DEFAULT ((now() AT TIME ZONE 'Africa/Monrovia')::date),employee_name text NOT NULL,employee_number text,office_id uuid REFERENCES public.offices(id),section_id uuid REFERENCES public.sections(id),duty_assignment text NOT NULL,activities text NOT NULL,tasks_completed text,challenges text,recommendations text,attachments jsonb NOT NULL DEFAULT '[]',signature text,status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Pending','Returned','Rejected','Approved')),stage integer NOT NULL DEFAULT 0,chain jsonb NOT NULL DEFAULT '[]',history jsonb NOT NULL DEFAULT '[]',revision integer NOT NULL DEFAULT 1,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(officer_id,report_date));
GRANT SELECT ON public.daily_reports TO authenticated; GRANT ALL ON public.daily_reports TO service_role;
ALTER TABLE public.daily_reports ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.command_report_reader(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM daily_reports r WHERE r.id=_id AND (r.created_by=auth.uid() OR public.has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]) OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.chain) a WHERE a->>'user_id'=auth.uid()::text))) $$;
REVOKE ALL ON FUNCTION public.command_report_reader(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_report_reader(uuid) TO authenticated;
CREATE POLICY daily_report_read ON public.daily_reports FOR SELECT TO authenticated USING(public.command_report_reader(id));
CREATE TRIGGER audit_daily_reports AFTER INSERT OR UPDATE OR DELETE ON public.daily_reports FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.compiled_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_number text NOT NULL UNIQUE DEFAULT ('LNPATS/COM/'||lpad(nextval('public.command_report_seq')::text,6,'0')),created_by uuid NOT NULL,title text NOT NULL,period text NOT NULL CHECK(period IN ('Daily Headquarters Report','Weekly Summary','Monthly Summary','Sectional Report','Departmental Report')),start_date date NOT NULL,end_date date NOT NULL CHECK(end_date>=start_date),source_ids uuid[] NOT NULL,source_snapshots jsonb NOT NULL,comments text,signature text NOT NULL,recipient_id uuid,status text NOT NULL DEFAULT 'Submitted',history jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.compiled_reports TO authenticated; GRANT ALL ON public.compiled_reports TO service_role;
ALTER TABLE public.compiled_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY compilation_read ON public.compiled_reports FOR SELECT TO authenticated USING(created_by=auth.uid() OR recipient_id=auth.uid() OR public.has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]));
CREATE TRIGGER audit_compiled_reports AFTER INSERT OR UPDATE OR DELETE ON public.compiled_reports FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
ALTER TABLE public.notifications ADD COLUMN event_key text;
CREATE UNIQUE INDEX command_notification_dedupe ON public.notifications(user_id,event_key) WHERE event_key IS NOT NULL AND user_id IS NOT NULL;
CREATE FUNCTION public.command_notify(_user uuid,_title text,_body text,_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _user IS NOT NULL THEN INSERT INTO notifications(user_id,title,body,event_key) VALUES(_user,_title,_body,_key) ON CONFLICT(user_id,event_key) WHERE event_key IS NOT NULL AND user_id IS NOT NULL DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.command_notify(uuid,text,text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.command_directory() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN jsonb_build_object('officers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'full_name',o.full_name,'employee_number',o.employee_number,'user_id',o.user_id,'office_id',o.office_id,'section_id',o.section_id,'supervisor_id',o.supervisor_id,'employment_status',o.employment_status)) FROM officers o WHERE o.employment_status='Active'),'[]'::jsonb),'sections',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'office_id',s.office_id,'section_head',s.section_head)) FROM sections s),'[]'::jsonb),'offices',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM offices),'[]'::jsonb),'appointments',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM reporting_lines r),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.command_directory() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_directory() TO authenticated;
CREATE FUNCTION public.command_assign(_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=nullif(_payload->>'officer_id','')::uuid; s uuid; k text:=_payload->>'kind'; required_role app_role; path uuid[]; cur uuid; BEGIN IF NOT public.has_any_role(auth.uid(),ARRAY['hr_admin']::app_role[]) THEN RAISE EXCEPTION 'HR administrator permission required'; END IF;
IF NOT EXISTS(SELECT 1 FROM officers WHERE id=o AND user_id IS NOT NULL AND employment_status='Active') THEN RAISE EXCEPTION 'Choose active personnel linked to an account'; END IF;
IF k='Supervisor' THEN s:=nullif(_payload->>'supervisor_id','')::uuid; IF s IS NOT NULL AND NOT EXISTS(SELECT 1 FROM officers WHERE id=s AND user_id IS NOT NULL AND employment_status='Active') THEN RAISE EXCEPTION 'Supervisor needs an active account'; END IF; cur:=s; path:=ARRAY[o]; WHILE cur IS NOT NULL LOOP IF cur=ANY(path) THEN RAISE EXCEPTION 'Reporting line cycle is not allowed'; END IF; path:=array_append(path,cur); SELECT supervisor_id INTO cur FROM officers WHERE id=cur; END LOOP; UPDATE officers SET supervisor_id=s WHERE id=o;
ELSIF k='Section Head' THEN required_role:='section_head'; IF NOT EXISTS(SELECT 1 FROM officers e JOIN user_roles r ON r.user_id=e.user_id WHERE e.id=o AND r.role IN (required_role,'system_admin')) THEN RAISE EXCEPTION 'Officer needs the Section Head role'; END IF; UPDATE sections SET section_head=o WHERE id=(_payload->>'section_id')::uuid AND office_id=(SELECT office_id FROM officers WHERE id=o); IF NOT FOUND THEN RAISE EXCEPTION 'Section must belong to the officer department'; END IF;
ELSE required_role:=CASE k WHEN 'Department Head' THEN 'assistant_commissioner'::app_role WHEN 'Deputy Commandant' THEN 'deputy_commandant'::app_role WHEN 'Deputy Commandant Administration' THEN 'dc_admin'::app_role WHEN 'Commandant' THEN 'commandant'::app_role WHEN 'Chief Procurement Officer' THEN 'procurement_admin'::app_role END; IF required_role IS NULL THEN RAISE EXCEPTION 'Invalid appointment'; END IF; IF NOT EXISTS(SELECT 1 FROM officers e JOIN user_roles r ON r.user_id=e.user_id WHERE e.id=o AND r.role IN (required_role,'system_admin')) THEN RAISE EXCEPTION 'Officer lacks the required appointment role'; END IF; IF k='Department Head' AND NOT EXISTS(SELECT 1 FROM officers WHERE id=o AND office_id=nullif(_payload->>'office_id','')::uuid) THEN RAISE EXCEPTION 'Department head must belong to the department'; END IF; INSERT INTO reporting_lines(kind,office_id,officer_id) VALUES(k,CASE WHEN k='Department Head' THEN nullif(_payload->>'office_id','')::uuid END,o) ON CONFLICT(kind,office_id) DO UPDATE SET officer_id=excluded.officer_id,updated_at=now(); END IF; END $$;
REVOKE ALL ON FUNCTION public.command_assign(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_assign(jsonb) TO authenticated;
CREATE FUNCTION public.command_chain(_officer uuid,_supply boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o officers; ids uuid[]; labels text[]; a officers; chain jsonb:='[]'; x integer; role_needed app_role; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO o FROM officers WHERE id=_officer; IF NOT FOUND THEN RAISE EXCEPTION 'Personnel profile required'; END IF;
ids:=ARRAY[o.supervisor_id,(SELECT section_head FROM sections WHERE id=o.section_id),(SELECT officer_id FROM reporting_lines WHERE kind='Department Head' AND office_id=o.office_id),(SELECT officer_id FROM reporting_lines WHERE kind=CASE WHEN _supply THEN 'Deputy Commandant Administration' ELSE 'Deputy Commandant' END AND office_id IS NULL),(SELECT officer_id FROM reporting_lines WHERE kind='Commandant' AND office_id IS NULL)]; labels:=ARRAY['Immediate Supervisor','Section Head','Department Head',CASE WHEN _supply THEN 'Deputy Commandant Administration' ELSE 'Deputy Commandant' END,'Commandant']; FOR x IN 1..5 LOOP SELECT * INTO a FROM officers WHERE id=ids[x] AND employment_status='Active'; IF NOT FOUND OR a.user_id IS NULL THEN RAISE EXCEPTION 'Assign an active % with an account before submitting',labels[x]; END IF; role_needed:=CASE x WHEN 2 THEN 'section_head'::app_role WHEN 3 THEN 'assistant_commissioner'::app_role WHEN 4 THEN CASE WHEN _supply THEN 'dc_admin'::app_role ELSE 'deputy_commandant'::app_role END WHEN 5 THEN 'commandant'::app_role END; IF role_needed IS NOT NULL AND NOT public.has_any_role(a.user_id,ARRAY[role_needed]) THEN RAISE EXCEPTION '% lacks the required role',labels[x]; END IF; IF a.user_id=o.user_id AND NOT public.has_role(auth.uid(),'system_admin') THEN RAISE EXCEPTION 'A requester cannot approve their own submission; assign another %',labels[x]; END IF; chain:=chain||jsonb_build_array(jsonb_build_object('level',labels[x],'officer_id',a.id,'user_id',a.user_id,'name',a.full_name)); END LOOP; RETURN chain; END $$;
REVOKE ALL ON FUNCTION public.command_chain(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_chain(uuid,boolean) TO authenticated;
CREATE FUNCTION public.command_validate_files(_files jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; BEGIN IF jsonb_typeof(_files)<>'array' OR jsonb_array_length(_files)>10 THEN RAISE EXCEPTION 'At most ten attachments allowed'; END IF; FOR f IN SELECT value FROM jsonb_array_elements(_files) LOOP IF split_part(f->>'path','/',1) IS DISTINCT FROM auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='command-files' AND name=f->>'path') THEN RAISE EXCEPTION 'Invalid attachment ownership'; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.command_validate_files(jsonb) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.daily_report_action(_id uuid,_action text,_payload jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o officers; r daily_reports; ch jsonb; sig text; ev jsonb; next_user uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; ev:=jsonb_build_object('action',_action,'actor_id',auth.uid(),'by',(SELECT full_name FROM profiles WHERE id=auth.uid()),'at',now(),'note',_payload->>'note');
IF _action IN ('save','submit') THEN SELECT * INTO o FROM officers WHERE user_id=auth.uid() AND employment_status='Active'; IF NOT FOUND THEN RAISE EXCEPTION 'HR must link your active personnel profile to your account'; END IF; IF nullif(trim(_payload->>'duty_assignment'),'') IS NULL OR nullif(trim(_payload->>'activities'),'') IS NULL THEN RAISE EXCEPTION 'Duty assignment and activities required'; END IF; IF (_payload->>'report_date')::date>(now() AT TIME ZONE 'Africa/Monrovia')::date THEN RAISE EXCEPTION 'Future reports are not allowed'; END IF; PERFORM public.command_validate_files(coalesce(_payload->'attachments','[]')); sig:=nullif(trim(_payload->>'signature'),''); IF _action='submit' AND sig IS NULL THEN RAISE EXCEPTION 'Signature required'; END IF; IF _id IS NOT NULL THEN SELECT * INTO r FROM daily_reports WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.created_by<>auth.uid() OR r.status NOT IN ('Draft','Returned') THEN RAISE EXCEPTION 'Only your draft or returned report may be changed'; END IF; IF r.report_date<>(_payload->>'report_date')::date THEN RAISE EXCEPTION 'Report date cannot change'; END IF; END IF; ch:=CASE WHEN _action='submit' THEN public.command_chain(o.id,false) ELSE '[]'::jsonb END;
IF _id IS NULL THEN INSERT INTO daily_reports(officer_id,created_by,report_date,employee_name,employee_number,office_id,section_id,duty_assignment,activities,tasks_completed,challenges,recommendations,attachments,signature,status,stage,chain,history,submitted_at) VALUES(o.id,auth.uid(),(_payload->>'report_date')::date,o.full_name,o.employee_number,o.office_id,o.section_id,_payload->>'duty_assignment',_payload->>'activities',_payload->>'tasks_completed',_payload->>'challenges',_payload->>'recommendations',coalesce(_payload->'attachments','[]'),sig,CASE WHEN _action='submit' THEN 'Pending' ELSE 'Draft' END,CASE WHEN _action='submit' THEN 1 ELSE 0 END,ch,jsonb_build_array(ev),CASE WHEN _action='submit' THEN now() END) RETURNING id INTO _id;
ELSE UPDATE daily_reports SET duty_assignment=_payload->>'duty_assignment',activities=_payload->>'activities',tasks_completed=_payload->>'tasks_completed',challenges=_payload->>'challenges',recommendations=_payload->>'recommendations',attachments=coalesce(_payload->'attachments','[]'),signature=sig,status=CASE WHEN _action='submit' THEN 'Pending' ELSE 'Draft' END,stage=CASE WHEN _action='submit' THEN 1 ELSE 0 END,chain=ch,history=history||jsonb_build_object('action','previous revision','revision',revision,'content',to_jsonb(r),'at',now())||ev,revision=revision+1,submitted_at=CASE WHEN _action='submit' THEN now() ELSE submitted_at END WHERE id=_id; END IF;
IF _action='submit' THEN PERFORM command_notify((ch->0->>'user_id')::uuid,'Daily report awaiting review',(SELECT report_number FROM daily_reports WHERE id=_id),_id::text||':submit:'||coalesce(r.revision,0)); END IF;
ELSIF _action IN ('approve','reject','return') THEN SELECT * INTO r FROM daily_reports WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.status<>'Pending' THEN RAISE EXCEPTION 'Pending report required'; END IF; IF NOT ((r.chain->(r.stage-1)->>'user_id')::uuid=auth.uid() OR public.has_role(auth.uid(),'system_admin')) THEN RAISE EXCEPTION 'Only the assigned reviewer may act'; END IF; IF r.created_by=auth.uid() AND NOT public.has_role(auth.uid(),'system_admin') THEN RAISE EXCEPTION 'Cannot approve your own report'; END IF; IF _action<>'approve' AND nullif(trim(_payload->>'note'),'') IS NULL THEN RAISE EXCEPTION 'Reason required'; END IF; UPDATE daily_reports SET status=CASE WHEN _action='return' THEN 'Returned' WHEN _action='reject' THEN 'Rejected' WHEN r.stage=5 THEN 'Approved' ELSE 'Pending' END,stage=CASE WHEN _action='approve' THEN r.stage+1 ELSE r.stage END,history=history||ev||jsonb_build_object('stage',r.stage,'signature',(SELECT full_name FROM profiles WHERE id=auth.uid())) WHERE id=_id; PERFORM command_notify(r.created_by,'Daily report '||_action,r.report_number,_id::text||':'||r.revision||':'||r.stage||':'||_action); IF _action='approve' AND r.stage<5 THEN PERFORM command_notify((r.chain->r.stage->>'user_id')::uuid,'Daily report awaiting review',r.report_number,_id::text||':'||r.revision||':pending:'||(r.stage+1)); END IF;
ELSE RAISE EXCEPTION 'Invalid report action'; END IF; RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.daily_report_action(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.daily_report_action(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.compile_daily_reports(_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; snaps jsonb; r daily_reports; recipient uuid; count_ids integer; rid uuid; ev jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(_payload->'source_ids'); IF coalesce(cardinality(ids),0)=0 THEN RAISE EXCEPTION 'Select source reports'; END IF; SELECT count(DISTINCT x) INTO count_ids FROM unnest(ids) x; IF count_ids<>cardinality(ids) THEN RAISE EXCEPTION 'Duplicate sources'; END IF; IF nullif(trim(_payload->>'title'),'') IS NULL OR nullif(trim(_payload->>'signature'),'') IS NULL THEN RAISE EXCEPTION 'Title and signature required'; END IF;
FOR r IN SELECT * FROM daily_reports WHERE id=ANY(ids) LOOP IF NOT command_report_reader(r.id) OR r.status NOT IN ('Pending','Approved') THEN RAISE EXCEPTION 'Submitted, accessible sources required'; END IF; IF r.report_date NOT BETWEEN (_payload->>'start_date')::date AND (_payload->>'end_date')::date THEN RAISE EXCEPTION 'Source outside selected period'; END IF; IF NOT public.has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.history) h WHERE h->>'actor_id'=auth.uid()::text AND h->>'action'='approve') THEN RAISE EXCEPTION 'Review and approve sources before compilation'; END IF; END LOOP;
SELECT count(*) INTO count_ids FROM daily_reports WHERE id=ANY(ids); IF count_ids<>cardinality(ids) THEN RAISE EXCEPTION 'Source unavailable'; END IF; SELECT * INTO r FROM daily_reports WHERE id=ids[1]; IF public.has_any_role(auth.uid(),ARRAY['commandant']::app_role[]) THEN recipient:=auth.uid(); ELSIF public.has_any_role(auth.uid(),ARRAY['deputy_commandant']::app_role[]) THEN recipient:=(r.chain->4->>'user_id')::uuid; ELSE SELECT (a->>'user_id')::uuid INTO recipient FROM jsonb_array_elements(r.chain) WITH ORDINALITY c(a,n) WHERE n>(SELECT min(n2) FROM jsonb_array_elements(r.chain) WITH ORDINALITY c2(a2,n2) WHERE a2->>'user_id'=auth.uid()::text) ORDER BY n LIMIT 1; END IF; IF recipient IS NULL THEN RAISE EXCEPTION 'Upward recipient not assigned'; END IF; SELECT jsonb_agg(to_jsonb(d)) INTO snaps FROM daily_reports d WHERE id=ANY(ids); ev:=jsonb_build_array(jsonb_build_object('action','compiled','actor_id',auth.uid(),'at',now())); INSERT INTO compiled_reports(created_by,title,period,start_date,end_date,source_ids,source_snapshots,comments,signature,recipient_id,history) VALUES(auth.uid(),_payload->>'title',_payload->>'period',(_payload->>'start_date')::date,(_payload->>'end_date')::date,ids,snaps,_payload->>'comments',_payload->>'signature',recipient,ev) RETURNING id INTO rid; PERFORM command_notify(recipient,'Compiled report submitted',_payload->>'title',rid::text); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.compile_daily_reports(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.compile_daily_reports(jsonb) TO authenticated;
CREATE FUNCTION public.command_file_reader(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM daily_reports r CROSS JOIN LATERAL jsonb_array_elements(r.attachments) a WHERE a->>'path'=_path AND command_report_reader(r.id)) OR EXISTS(SELECT 1 FROM compiled_reports c CROSS JOIN LATERAL jsonb_array_elements(c.source_snapshots) d CROSS JOIN LATERAL jsonb_array_elements(d->'attachments') a WHERE a->>'path'=_path AND (c.created_by=auth.uid() OR c.recipient_id=auth.uid() OR has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]))) $$;
REVOKE ALL ON FUNCTION public.command_file_reader(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_file_reader(text) TO authenticated;
CREATE POLICY command_file_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='command-files' AND split_part(name,'/',1)=auth.uid()::text);
CREATE POLICY command_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='command-files' AND public.command_file_reader(name));
CREATE FUNCTION public.command_report_summary(_date date DEFAULT ((now() AT TIME ZONE 'Africa/Monrovia')::date)) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE all_access boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; all_access:=public.has_any_role(auth.uid(),ARRAY['commandant','deputy_commandant']::app_role[]); RETURN (SELECT jsonb_build_object('date',_date,'workday',extract(isodow from _date) BETWEEN 1 AND 5,'expected',count(*),'submitted',count(*) FILTER(WHERE EXISTS(SELECT 1 FROM daily_reports d WHERE d.officer_id=o.id AND d.report_date=_date AND d.submitted_at IS NOT NULL)),'missing',coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.full_name,'employee_number',o.employee_number,'supervisor_id',o.supervisor_id,'office_id',o.office_id)) FILTER(WHERE NOT EXISTS(SELECT 1 FROM daily_reports d WHERE d.officer_id=o.id AND d.report_date=_date AND d.submitted_at IS NOT NULL)),'[]'::jsonb)) FROM officers o WHERE o.employment_status='Active' AND o.user_id IS NOT NULL AND (all_access OR o.user_id=auth.uid() OR EXISTS(SELECT 1 FROM officers s WHERE s.id=o.supervisor_id AND s.user_id=auth.uid()) OR EXISTS(SELECT 1 FROM reporting_lines l JOIN officers h ON h.id=l.officer_id WHERE l.kind='Department Head' AND l.office_id=o.office_id AND h.user_id=auth.uid()))); END $$;
REVOKE ALL ON FUNCTION public.command_report_summary(date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_report_summary(date) TO authenticated;
CREATE FUNCTION public.daily_report_alerts(_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date:=(_at AT TIME ZONE 'Africa/Monrovia')::date; hr integer:=extract(hour from _at AT TIME ZONE 'Africa/Monrovia'); o officers; supervisor uuid; dept uuid; count_sent integer:=0; title text; BEGIN IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Scheduled task only'; END IF; IF extract(isodow from d) NOT BETWEEN 1 AND 5 OR hr NOT BETWEEN 15 AND 18 THEN RETURN 0; END IF; title:=CASE hr WHEN 15 THEN 'Daily report reminder' WHEN 16 THEN 'Second daily report reminder' WHEN 17 THEN 'Daily Report Overdue' ELSE 'Daily report escalation' END; FOR o IN SELECT * FROM officers e WHERE e.employment_status='Active' AND e.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM daily_reports r WHERE r.officer_id=e.id AND r.report_date=d AND r.submitted_at IS NOT NULL) LOOP SELECT user_id INTO supervisor FROM officers WHERE id=o.supervisor_id; SELECT e.user_id INTO dept FROM reporting_lines l JOIN officers e ON e.id=l.officer_id WHERE l.kind='Department Head' AND l.office_id=o.office_id; IF hr<18 THEN PERFORM command_notify(o.user_id,title,o.full_name||' · '||d,d||':'||o.id||':'||hr); END IF; IF hr>=17 THEN PERFORM command_notify(supervisor,title,o.full_name||' has not submitted a daily report for '||d,d||':'||o.id||':'||hr); END IF; IF hr=18 THEN PERFORM command_notify(dept,title,o.full_name||' has not submitted a daily report for '||d,d||':'||o.id||':'||hr); END IF; count_sent:=count_sent+1; END LOOP; RETURN count_sent; END $$;
REVOKE ALL ON FUNCTION public.daily_report_alerts(timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.daily_report_alerts(timestamptz) TO service_role;
GRANT USAGE ON SEQUENCE public.command_report_seq TO service_role;
COMMENT ON TABLE public.reporting_lines IS 'Named command appointments only; canonical supervisor and section head remain on officers and sections. Submission snapshots fail closed on missing assignments.';